    await page.mouse.down();
    for (let i = 0; i <= 40; i++) {
      const a = (i / 40) * Math.PI * 2;
      await page.mouse.move(cx + Math.cos(a) * r * (1 + 0.25 * Math.sin(a * 3)), cy + Math.sin(a) * r * (1 + 0.15 * Math.cos(a * 2)));
    }
    await page.mouse.up();
    await page.waitForTimeout(900);
    await page.screenshot({ path: `/tmp/opencode/${name}-drawloop.jpg`, type: 'jpeg', quality: 80 });
    console.log(name, 'btn disabled', await page.evaluate(() => document.querySelector('#btn-build').disabled));
