import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: false, executablePath: '/opt/google/chrome/chrome', args: ['--enable-gpu','--ignore-gpu-blocklist','--use-angle=vulkan','--enable-unsafe-webgpu','--use-vulkan=swiftshader','--disable-vulkan-surface','--no-sandbox'] });

async function resultsFor(name, width, height, mobile, laps, ai) {
  const ctx = await browser.newContext({ viewport: { width, height }, deviceScaleFactor: 1, isMobile: mobile, hasTouch: mobile });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForFunction(() => window.__apex && getComputedStyle(document.querySelector('#loading')).display === 'none', null, { timeout: 45000 });
  await page.evaluate(({laps, ai}) => { document.querySelector('#setup-laps').value = String(laps); document.querySelector('#setup-ai').value = String(ai); }, {laps, ai});
  await page.evaluate(() => window.__apex.demoRace(0));
  await page.waitForFunction(() => window.__apex.race, null, { timeout: 20000 });
  await page.evaluate(() => { const r = window.__apex.race; r.countdownT = 0; window.__apex.startRaceNow(); });
  const out = await page.evaluate(() => {
    const r = window.__apex.race;
    let n = 0;
    while (r.state !== 'finished' && n < 30000) { window.__apex.tick(1/60); n++; }
    let k = 0;
    while (!r.resultsShown && k < 500) { window.__apex.tick(1/60); k++; }
    return { n, k, state: r.state, shown: r.resultsShown, time: r.player.finishTime, best: r.player.bestLap, pos: r.player.finishPosition, rows: [...document.querySelectorAll('#results-rows .results-row')].map(e => e.innerText.replace(/\n/g, ' ')) };
  });
  console.log(name, JSON.stringify(out));
  await page.waitForTimeout(500);
  await page.screenshot({ path: `/tmp/opencode/${name}-results2.jpg`, type: 'jpeg', quality: 82 });
  console.log(name, 'errors', errors);
