await page.evaluate(() => { document.querySelector('#setup-laps').value = '1'; document.querySelector('#setup-ai').value = '3'; });
await page.evaluate(() => window.__apex.demoRace(0));
await page.waitForFunction(() => window.__apex.race, null, { timeout: 20000 });
const out = await page.evaluate(() => {
  const r = window.__apex.race;
  const tr = r.track;
  const N = tr.N;
  r.countdownT = 0; window.__apex.startRaceNow();
  const p = r.player;
  let n = 0, off = 0, maxSpeed = 0;
  while (r.state === 'racing' && n < 30000) {
    // find nearest sample near last index
    let best = p.lastIndex, bd = Infinity;
    for (let k = -80; k <= 160; k++) {
      const i = (p.lastIndex + k + N) % N;
      const s = tr.samples[i];
      const d = (p.pos.x - s.x) ** 2 + (p.pos.z - s.z) ** 2;
      if (d < bd) { bd = d; best = i; }
    }
    const s = tr.samples[best];
    const lead = tr.samples[(best + Math.max(3, Math.round(10 / tr.step))) % N];
    // aim at a point ahead, corrected toward the centerline
    const lateral = (p.pos.x - s.x) * s.nx + (p.pos.z - s.z) * s.nz;
    const targetX = lead.x - s.nx * lateral * 0.8;
    const targetZ = lead.z - s.nz * lateral * 0.8;
    let err = Math.atan2(targetX - p.pos.x, targetZ - p.pos.z) - p.yaw;
    err = ((err + Math.PI) % (2 * Math.PI) + 2 * Math.PI) % (2 * Math.PI) - Math.PI;
    window.__apex.setDemoInput({ left: err > 0.02, right: err < -0.02, gas: false, brake: false });
    window.__apex.tick(1 / 60);
    if (p.offroad) off++;
    maxSpeed = Math.max(maxSpeed, p.vLong);
    n++;
  }
  window.__apex.setDemoInput({ left: false, right: false });
  return {
    n, state: r.state, lap: p.lapsCompleted, best: p.bestLap, last: p.lastLap,
    offFrames: off, maxKmh: Math.round(maxSpeed * 3.6), finishPos: p.finishPosition,
    ai: r.ai.map(a => ({ name: a.name, fin: a.finished, t: a.finishTime })),
    time: r.time
  };
});
