          camera.position.x = 1.45 + 5.7 * distScale + Math.sin(t * 0.16) * 0.12;
          camera.position.y = 0.8 + 1.95 * distScale + Math.sin(t * 0.21) * 0.06;
          camera.position.z = 8.9 * distScale;
          camera.lookAt(1.45, 0.8, 0);
