  display: inline-grid; place-items: center; width: 38px; height: 38px;
  border: 1px solid var(--line); border-radius: 50%;
  background: rgba(255,255,255,.025); color: var(--cream);
  transition: background .2s, border-color .2s, transform .2s;
}
.icon-btn svg { width: 17px; height: 17px; }
.icon-btn:hover { background: rgba(255,255,255,.08); border-color: rgba(255,255,255,.3); }
.icon-btn.is-muted .wave { opacity: .12; }
.icon-btn.is-muted::after {
  content: ''; position: absolute; width: 20px; height: 1.5px; background: currentColor; transform: rotate(-45deg);
}
.icon-btn { position: relative; }

/* ─────────────────────────────── menu ─────────────────────────────── */
#screen-menu {
  display: grid; grid-template-rows: auto 1fr auto; grid-template-columns: minmax(0, 1fr);
  padding: 26px 42px 20px;
  background:
    linear-gradient(90deg, rgba(6,7,9,.96) 0%, rgba(6,7,9,.86) 30%, rgba(6,7,9,.24) 62%, rgba(6,7,9,.02) 100%),
    linear-gradient(180deg, rgba(5,6,8,.82) 0%, transparent 16%, transparent 80%, rgba(5,6,8,.92) 100%);
}
#screen-menu::before {
  content: ''; position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(circle at 75% 45%, transparent 0%, rgba(5,6,8,.25) 46%, rgba(5,6,8,.62) 100%);
}
.menu-top { display: flex; align-items: center; justify-content: space-between; position: relative; z-index: 2; }
.brand { display: inline-flex; align-items: center; gap: 10px; }
.brand-mark { width: 38px; height: 38px; display: grid; place-items: center; color: var(--orange); }
.brand-mark svg { width: 34px; height: 34px; }
.brand-word {
  font-family: var(--font-display); font-weight: 700; font-size: 25px; letter-spacing: .06em; line-height: 1;
  color: var(--cream);
}
.brand-word span { color: var(--orange); }
.brand-small .brand-mark { width: 30px; height: 30px; }
.brand-small .brand-mark svg { width: 27px; height: 27px; }
.brand-small .brand-word { font-size: 21px; }
.menu-top-right { display: flex; align-items: center; gap: 12px; }
.live-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--orange); box-shadow: 0 0 0 4px rgba(255,77,31,.12); animation: pulse 2.2s infinite; }
@keyframes pulse { 0%,100% { box-shadow: 0 0 0 3px rgba(255,77,31,.1); } 50% { box-shadow: 0 0 0 7px rgba(255,77,31,.02); } }

.menu-content {
  position: relative; z-index: 2;
  display: grid; grid-template-columns: minmax(0, 1fr) 370px;
  align-items: center; gap: 50px; padding: 2vh 0;
  min-width: 0;
}
.menu-copy { max-width: 700px; min-width: 0; padding-left: 2px; }
.eyebrow {
  display: flex; align-items: center; gap: 12px;
  font-family: var(--font-mono); font-size: 10px; letter-spacing: .3em; color: var(--orange);
  text-transform: uppercase;
}
.eyebrow-line { width: 42px; height: 1px; background: var(--orange); display: inline-block; }
.menu-copy h1 {
  margin: 22px 0 20px;
  font-family: var(--font-display); font-weight: 700;
  font-size: clamp(82px, 11vw, 154px);
  line-height: .76; letter-spacing: -.025em;
  text-transform: uppercase;
}
.menu-copy h1 em {
  display: inline-block; font-style: normal;
  color: transparent;
  -webkit-text-stroke: 1.5px rgba(243,239,229,.86);
  position: relative; margin-top: .06em;
  text-shadow: 0 0 60px rgba(255,77,31,.08);
}
.menu-copy h1 em::after {
  content: ''; position: absolute; right: -26px; bottom: .16em;
  width: 13px; height: 13px; background: var(--orange); border-radius: 50%;
}
.lede {
  max-width: 470px; margin: 0 0 30px;
  color: #b9bbc0; font-size: 15.5px; font-weight: 300; line-height: 1.7;
}
.lede b { color: var(--cream); font-weight: 600; }
.race-setup {
  display: flex; align-items: end; flex-wrap: wrap; gap: 10px;
  margin: -10px 0 22px;
}
.race-setting { display: flex; flex-direction: column; gap: 6px; }
.race-setting > span { color: var(--dim-2); font-size: 8px; letter-spacing: .18em; }
.race-setting select {
  min-width: 116px; padding: 9px 30px 9px 11px;
  border: 1px solid rgba(255,255,255,.14); border-radius: 2px;
  background: rgba(15,17,21,.9); color: var(--cream);
  font: 600 11px var(--font-mono); letter-spacing: .08em;
  outline: none; cursor: pointer;
}
.race-setting select:focus-visible { border-color: var(--orange); box-shadow: 0 0 0 2px rgba(255,77,31,.18); }
.race-setting option { background: #101216; color: var(--cream); }
.race-setup-note { align-self: center; padding: 0 2px 9px; color: var(--dim-2); font-size: 8px; letter-spacing: .12em; }
.menu-actions { display: flex; flex-wrap: wrap; align-items: stretch; gap: 12px; }
.menu-actions .btn { flex-direction: column; gap: 2px; }
.menu-actions .btn svg { position: absolute; right: 22px; top: 50%; translate: 0 -50%; }
.menu-actions .btn-primary { padding-right: 58px; }
.menu-actions .btn-ghost { padding-right: 22px; align-items: flex-start; background: rgba(8,9,12,.52); backdrop-filter: blur(10px); }
.menu-meta { display: flex; align-items: center; gap: 26px; margin-top: 42px; }
.menu-meta > div:not(.meta-divider) { display: flex; align-items: baseline; gap: 8px; }
.menu-meta strong { font-family: var(--font-display); font-size: 16px; color: var(--orange); font-weight: 600; }
.menu-meta span { font-family: var(--font-mono); font-size: 9px; letter-spacing: .16em; color: var(--dim); }
.meta-divider { width: 1px; height: 26px; background: var(--line); }
.meta-ref { display: flex; flex-direction: column; gap: 4px; }
.meta-ref b { font-family: var(--font-display); font-weight: 600; font-size: 12px; letter-spacing: .12em; color: #c9c9c9; }

.menu-card {
  position: relative; align-self: end; margin-bottom: 2vh;
  background: linear-gradient(155deg, rgba(18,21,27,.85), rgba(10,12,16,.72));
  border: 1px solid rgba(255,255,255,.1);
  backdrop-filter: blur(16px);
  clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 0 100%);
  box-shadow: 0 40px 90px -30px rgba(0,0,0,.8);
  padding: 18px;
@media (max-width: 1180px) {
  .menu-content { grid-template-columns: minmax(0, 1fr) 330px; gap: 32px; }
  #screen-menu { padding: 22px 30px 16px; }
  #screen-garage { padding: 22px 30px 18px; }
  .garage-dock-body { gap: 20px; }
  .garage-swatches { grid-template-columns: repeat(10, minmax(0, 1fr)); }
  .draw-layout { grid-template-columns: minmax(0, 1fr) 340px; padding: 14px 18px 18px; }
  .controls-hint { display: none; }
}
@media (max-width: 900px) {
  body { overflow: hidden; }
  #screen-menu { padding: 18px 20px 14px; background: linear-gradient(180deg, rgba(6,7,9,.94), rgba(6,7,9,.55) 45%, rgba(6,7,9,.94)); }
  .menu-content { grid-template-columns: 1fr; align-content: center; gap: 26px; }
  .menu-copy h1 { font-size: clamp(66px, 16vw, 112px); margin: 18px 0 14px; }
  .lede { font-size: 13.5px; margin-bottom: 22px; }
  .menu-card { display: none; }
  .menu-meta { margin-top: 26px; gap: 18px; flex-wrap: wrap; }
  .menu-top-right .mono { display: none; }
  .menu-bottom { display: none; }
  .draw-header { height: 58px; padding: 0 16px; }
  .steps .step { padding: 6px 7px; font-size: 7px; }
  .steps .step span { font-size: 9px; }
  .step + .step::before { display: none; }
  .draw-layout { display: flex; flex-direction: column; padding: 10px 12px 14px; gap: 10px; overflow-y: auto; height: calc(100% - 58px); }
  .canvas-shell { flex: none; height: 53vh; min-height: 330px; }
  .canvas-stage { margin: 8px; }
  .canvas-bottom { display: none; }
  .draw-panel { flex: none; overflow: visible; }
  .panel-scroll { padding: 18px; overflow: visible; }
  .draw-panel h2 { font-size: 28px; }
  .panel-copy { display: none; }
  .stat-grid { display: grid; grid-template-columns: repeat(3, 1fr); }
  .stat { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; padding: 8px 10px 8px 0; border-bottom: 0; }
  .stat + .stat { border-left: 1px solid var(--line-soft); padding-left: 12px; }
  .stat strong { font-size: 22px; }
  .stat span { order: 0; }
  .stat small { display: none; }
  .difficulty { margin-bottom: 12px; }
  .panel-actions { grid-template-columns: 1.4fr 1fr; }
  .microcopy { display: none; }
  .build-steps { grid-template-columns: 1fr 1fr; }
  .build-inner { width: 88vw; }
  .build-brand { margin-bottom: 34px; }
  #screen-garage { padding: 14px 16px 14px; overflow: hidden; grid-template-rows: auto minmax(150px, 1fr) auto; }
  .garage-header { height: 44px; }
  .garage-header-title { display: none; }
  .garage-stage-copy { top: 2vh; max-width: 245px; }
  .garage-stage-copy h2 { font-size: 36px; margin: 10px 0 8px; }
  .garage-stage-copy p { display: none; }
  .garage-live { top: auto; bottom: 1vh; padding: 8px 12px; }
  .garage-dock { padding: 12px 16px 9px; max-height: 47vh; }
  .garage-parts-row { flex-wrap: wrap; gap: 8px; }
  .garage-dock-body { grid-template-columns: 1fr 1fr; gap: 16px; padding: 12px 0 10px; }
  .garage-stickers-panel { grid-column: 1 / -1; }
  .garage-swatches { grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 8px; }
  .garage-dock-foot { display: none; }
  .race-setup-panel { flex-wrap: wrap; }
  .race-setup-panel .race-setting { min-width: 120px; }
  .race-setup-panel .race-setup-note { max-width: none; }
}

@media (max-width: 760px) {
  #screen-menu { padding: 16px 16px 12px; }
  .brand-word { font-size: 21px; }
  .menu-copy h1 em::after { right: -14px; width: 8px; height: 8px; }
  .menu-actions { flex-direction: column; align-items: stretch; max-width: 340px; }
  .menu-actions .btn { width: 100%; }
  .menu-meta { gap: 14px; }
  .meta-divider, .meta-ref { display: none; }
  .menu-card { display: none; }
  .garage-stage-copy { display: none; }
  .garage-stage-copy h2 { font-size: 30px; }
  .garage-stage-copy .eyebrow { display: none; }
  .garage-live { left: 0; right: auto; top: 2px; bottom: auto; gap: 8px; padding: 6px 9px; }
  .garage-live strong { font-size: 16px; }
  .garage-live .garage-live-name { display: none; }
  .garage-orbit-hint { top: 2px; bottom: auto; left: auto; right: 0; transform: none; font-size: 7px; padding: 5px 9px; }
  .garage-orbit-hint-more { display: none; }
  .garage-orbit-hint.is-used { transform: translateY(-6px); }
  .garage-dock { padding: 10px 12px 8px; max-height: 49vh; }
  .garage-dock-body { grid-template-columns: 1fr; gap: 14px; }
  .garage-stickers-panel { grid-column: auto; }
  .garage-stickers { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .garage-reset { margin-left: 0; }
  .garage-hex input { width: 66px; }
  .hud-top { top: 12px; left: 12px; right: 12px; gap: 8px; }
  .hud-position { min-width: 0; padding: 8px 12px; gap: 8px; }
  .pos-big { font-size: 40px; }
  .pos-meta strong { font-size: 11px; }
  .pos-meta .mono { display: none; }
  .hud-left { gap: 6px; }
  .leaderboard { width: 184px; border-top-width: 1px; }
  .lb-head { grid-template-columns: 18px 3px 1fr 54px; gap: 6px; padding: 4px 7px; font-size: 6px; }
  .lb-row { grid-template-columns: 18px 3px 1fr 54px; gap: 6px; padding: 3.5px 7px; }
  .lb-row .lb-pos { font-size: 10px; }
  .lb-row .lb-col { height: 12px; width: 3px; }
  .lb-row .lb-name { font-size: 10px; }
  .lb-row .lb-gap { font-size: 8px; }
  .lb-row.is-leader .lb-gap { font-size: 6px; }
  .hud-timing { min-width: 0; }
  .timing-main { padding: 7px 12px; min-width: 0; }
  .timing-main span { display: none; }
  .timing-main strong { font-size: 21px; }
  .timing-splits { display: none; }
  .hud-pause { width: 32px; height: 32px; }
  .hud-bottom { left: 12px; right: 12px; bottom: 12px; align-items: flex-end; }
  .speedo { width: 190px; height: 105px; padding: 6px; background: rgba(10,12,16,.55); }
  .speedo-arc { left: 12px; top: 8px; width: 166px; height: 94px; }
  .speedo-readout { left: 34px; top: 36px; width: 120px; }
  .speedo-readout strong { font-size: 40px; }
  .speedo-readout .mono { margin-top: 2px; font-size: 6px; }
  .gear-box { right: 10px; bottom: 10px; }
  .gear-box strong { font-size: 17px; }
  .throttle-strip { display: none; }
  .minimap-panel { width: 150px; padding: 5px; }
  .minimap-head { padding-bottom: 3px; }
  .minimap-head .mono:last-child { display: none; }
  #minimap { height: 72px; }
  .minimap-foot { display: none; }
  .touch-controls { display: flex; position: absolute; left: 12px; right: 12px; bottom: 120px; justify-content: space-between; align-items: flex-end; pointer-events: none; }
  .touch-steer, .touch-pedals { display: flex; gap: 10px; pointer-events: auto; }
  .touch-controls button {
    width: 66px; height: 66px; border-radius: 50%;
    border: 1px solid rgba(255,255,255,.2);
    background: rgba(12,14,18,.58); backdrop-filter: blur(8px);
    font-family: var(--font-display); font-weight: 600; font-size: 11px; letter-spacing: .08em;
    display: grid; place-items: center; touch-action: none; user-select: none;
    color: var(--cream);
  }
  .touch-controls button svg { width: 24px; height: 24px; }
  .touch-controls button:active, .touch-controls button.is-down { background: var(--orange); color: #120b08; border-color: transparent; }
  .tap-gas { width: 74px !important; height: 74px !important; background: rgba(255,77,31,.22) !important; border-color: rgba(255,77,31,.55) !important; }
  .race-message { top: 27%; font-size: 30px; }
  .off-track { top: 27%; }
  .modal { padding: 24px 22px; }
  .modal h2 { font-size: 44px; }
  .results-modal { padding: 20px; max-height: 92vh; overflow-y: auto; }
  .results-hero { gap: 16px; padding: 14px 0; }
  .results-place { padding-right: 16px; }
  .results-place span { font-size: 62px; }
  .results-copy h2 { font-size: 34px; }
  .results-grid { grid-template-columns: 1fr 1fr; }
  .result-stat:nth-child(3) { border-left: 0; border-top: 1px solid var(--line-soft); }
  .result-stat:nth-child(4) { border-top: 1px solid var(--line-soft); }
  .results-actions { flex-direction: column; }
  .results-row { grid-template-columns: 28px 1fr 34px 74px; font-size: 10px; }
  .countdown small { margin-top: 10px; }
  .toast { bottom: 22px; }
}

@media (max-width: 560px) {
  .draw-header { padding: 0 12px; }
  .draw-header .steps { display: none; }
}

@media (max-width: 440px) {
  .menu-copy h1 { font-size: 64px; }
  .eyebrow { font-size: 8px; letter-spacing: .2em; }
  .lede { font-size: 12.5px; max-width: 320px; }
  .draw-header-right .icon-btn { display: none; }
  .canvas-shell { height: 48vh; min-height: 300px; }
  .panel-actions { grid-template-columns: 1fr; }
  .difficulty { margin-bottom: 10px; }
  .stat-grid { margin-bottom: 12px; }
  .modal-screen { padding: 10px; }
  .modal h2 { font-size: 38px; }
  .speedo { width: 160px; height: 96px; }
  .speedo-arc { left: 6px; }
  .minimap-panel { width: 120px; }
  #minimap { height: 60px; }
  .touch-controls button { width: 58px; height: 58px; }
  .tap-gas { width: 66px !important; height: 66px !important; }
}

@media (hover: hover) and (pointer: fine) {
  .touch-controls { display: none !important; }
}

/* Keep the build controls visible on short laptop screens. */
@media (max-height: 820px) and (min-width: 901px) {
  .microcopy { display: none; }
}
@media (max-height: 740px) and (min-width: 901px) {
  .panel-copy { display: none; }
  .draw-panel h2 { font-size: 29px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

