import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: false, executablePath: '/opt/google/chrome/chrome', args: ['--enable-gpu','--ignore-gpu-blocklist','--use-angle=vulkan','--enable-unsafe-webgpu','--use-vulkan=swiftshader','--disable-vulkan-surface','--no-sandbox'] });
for (const [name,w,h] of [['short',1280,600],['short2',1280,500],['small',900,600],['tiny',640,360]]) {
  const ctx = await browser.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForFunction(() => window.__apex && getComputedStyle(document.querySelector('#loading')).display === 'none', null, { timeout: 45000 });
  await page.waitForTimeout(500);
  const info = await page.evaluate(() => {
    const r = document.querySelector('#btn-start').getBoundingClientRect();
    const g = document.querySelector('#btn-garage').getBoundingClientRect();
    const menu = document.querySelector('#screen-menu').getBoundingClientRect();
    return { start: {top:r.top,bottom:r.bottom,left:r.left,right:r.right}, garage:{top:g.top,bottom:g.bottom}, menu:{h:menu.height}, innerH:innerHeight };
  });
  console.log(name, JSON.stringify(info));
  await page.screenshot({ path: `/tmp/opencode/${name}-menu.jpg`, type: 'jpeg', quality: 80 });
  await ctx.close();
}
await browser.close();

import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: false, executablePath: '/opt/google/chrome/chrome', args: ['--enable-gpu','--ignore-gpu-blocklist','--use-angle=vulkan','--enable-unsafe-webgpu','--use-vulkan=swiftshader','--disable-vulkan-surface','--no-sandbox'] });
const ctx = await browser.newContext({ viewport: { width: 844, height: 390 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
const page = await ctx.newPage();
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002/?demo=race&go=1', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex?.race && getComputedStyle(document.querySelector('#loading')).display === 'none', null, { timeout: 45000 });
await page.waitForTimeout(1000);
await page.screenshot({ path: '/tmp/opencode/land-race.jpg', type: 'jpeg', quality: 80 });
await page.evaluate(() => window.__apex.pauseRace());
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/opencode/land-pause.jpg', type: 'jpeg', quality: 80 });
const info = await page.evaluate(() => {
  const els = ['screen-pause','btn-resume','btn-restart-race','btn-new-track'];
  const out = {};
  for (const id of els) { const r=document.getElementById(id).getBoundingClientRect(); out[id]={top:r.top,bottom:r.bottom,h:r.height}; }
  const t=document.querySelector('.touch-controls'); const s=document.querySelector('.speedo'); const m=document.querySelector('.minimap-panel');
  out.touch=getComputedStyle(t).display; out.speedo=s.getBoundingClientRect().toJSON(); out.mini=m.getBoundingClientRect().toJSON();
  return {out, innerH:innerHeight};
});
console.log(JSON.stringify(info,null,1));
console.log('errors', errors);
await browser.close();

