  await page.goto('http://localhost:3002/?demo=race&go=1', { waitUntil: 'load' });
  await page.waitForFunction(() => window.__apex?.race && getComputedStyle(document.querySelector('#loading')).display === 'none', null, { timeout: 45000 });
  await page.waitForTimeout(700);
  await page.screenshot({ path: `/tmp/opencode/${name}-race2.jpg`, type: 'jpeg', quality: 82 });
  const out = await page.evaluate(() => {
    const r = window.__apex.race;
    let n = 0;
    while (r.state !== 'finished' && n < 30000) { window.__apex.tick(1/60); n++; }
    let k = 0;
