import { createRequire } from 'node:module';
import { join } from 'node:path';

const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const URL = process.env.CAPTURE_URL || 'http://localhost:3002';
const OUT = '/tmp/opencode';
const results = [];
const errors = [];

function log(...a) { console.log(...a); }

async function shot(page, name) {
  await page.screenshot({ path: `${OUT}/${name}.jpg`, type: 'jpeg', quality: 62 });
  log('shot', name);
}

async function waitReady(page) {
  await page.waitForFunction(() => window.__apex && document.querySelector('#screen-menu.is-active') &&
    getComputedStyle(document.querySelector('#loading')).display === 'none', null, { timeout: 30000 });
  await page.evaluate(async () => { await document.fonts?.ready; });
}

async function startRaceViaUI(page, laps = 1, ai = 3) {
  await page.click('#btn-start');
  await page.waitForSelector('#screen-draw.is-active', { timeout: 5000 });
  await page.click('#btn-example');
  await page.waitForFunction(() => !document.querySelector('#btn-build').disabled, null, { timeout: 8000 });
  await page.selectOption('#setup-laps', String(laps));
  await page.selectOption('#setup-ai', String(ai));
  await page.click('#btn-build');
  await page.waitForFunction(() => window.__apex.race && window.__apex.race.state !== 'build', null, { timeout: 15000 });
}

// Drive using the track's own samples so a real race can be completed headlessly.
async function autopilot(page, { ticks = 12000, dt = 1 / 60, stopAtResults = true } = {}) {
  return await page.evaluate(async ({ ticks, dt, stopAtResults }) => {
    const a = window.__apex;
    const sleep = () => new Promise((r) => setTimeout(r, 0));
    let ticksDone = 0;
    const wrap = (v) => Math.atan2(Math.sin(v), Math.cos(v));
    for (let i = 0; i < ticks; i++) {
      const r = a.race;
      if (!r) break;
      if (r.state === 'countdown') { a.tick(dt); ticksDone++; continue; }
      if (r.state === 'paused') break;
      if (r.state === 'finished' && stopAtResults) {
        if (r.resultsShown) break;
        a.tick(dt); ticksDone++; continue;
      }
      if (r.state === 'racing') {
        const p = r.player;
        const tr = r.track;
        const speed = Math.max(14, Math.abs(p.vLong));
        const ahead = Math.min(110, 20 + speed * 1.15);
        const idx = (Math.floor(p.sNorm * tr.N) + Math.round(ahead / tr.step)) % tr.N;
        const s = tr.samples[idx];
        const targetYaw = Math.atan2(s.x - p.pos.x, s.z - p.pos.z);
        const err = wrap(targetYaw - p.yaw);
        a.setDemoInput({
          left: err > 0.035,
          right: err < -0.035,
          gas: false,
          brake: false
        });
      }
      a.tick(dt);
      ticksDone++;
      if (i % 400 === 0) await sleep();
    }
    a.setDemoInput({ left: false, right: false, gas: false, brake: false });
    return {
      ticks: ticksDone,
      state: a.race?.state,
      resultsShown: !!a.race?.resultsShown,
      laps: a.race?.player?.lapsCompleted,
      totalLaps: a.race?.totalLaps,
      time: a.race?.time,
      finished: !!a.race?.player?.finished
    };
  }, { ticks, dt, stopAtResults });
}

async function modalFits(page, sel) {
  return await page.evaluate((sel) => {
    const el = document.querySelector(sel);
    if (!el) return { found: false };
    const r = el.getBoundingClientRect();
    const vh = window.innerHeight, vw = window.innerWidth;
    return {
      found: true,
      top: Math.round(r.top), bottom: Math.round(r.bottom),
      left: Math.round(r.left), right: Math.round(r.right),
      fitsViewport: r.top >= -1 && r.left >= -1 && r.right <= vw + 1 && r.bottom <= vh + 1,
      needsScroll: el.scrollHeight > el.clientHeight + 1,
      scrollH: el.scrollHeight, clientH: el.clientHeight
    };
  }, sel);
}

async function runDesktop(browser) {
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  const errs = [];
  page.on('pageerror', (e) => errs.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errs.push('console: ' + m.text()); });
  await page.goto(URL, { waitUntil: 'domcontentloaded' });
  await waitReady(page);
  await shot(page, 'v-menu-desk');

  const menuOverflow = await page.evaluate(() => ({
    scrollH: document.querySelector('#screen-menu').scrollHeight,
    clientH: document.querySelector('#screen-menu').clientHeight,
    startVisible: (() => { const r = document.querySelector('#btn-start').getBoundingClientRect(); return r.top >= 0 && r.bottom <= innerHeight; })()
  }));

  await startRaceViaUI(page, 1, 3);
  await page.waitForFunction(() => window.__apex.race.state === 'racing', null, { timeout: 10000 });
  await page.waitForTimeout(1200);
  await shot(page, 'v-race-desk');

  const drawn = await autopilot(page, { ticks: 20000 });
  log('desktop race result', drawn);
  await page.waitForSelector('#screen-results.is-active', { timeout: 8000 });
  await page.waitForTimeout(350);
  await shot(page, 'v-results-desk');
  const resultsFit = await modalFits(page, '.results-modal');

  // Restart from results, verify a clean race and pause modal.
  await page.click('#btn-race-again');
  await page.waitForFunction(() => window.__apex.race && window.__apex.race.state !== 'paused' && !document.querySelector('#screen-results.is-active'), null, { timeout: 6000 });
  await page.waitForTimeout(500);
  await page.keyboard.press('Escape');
  await page.waitForSelector('#screen-pause.is-active', { timeout: 4000 });
  await shot(page, 'v-pause-desk');
  const pauseFit = await modalFits(page, '.pause-modal');
  await page.click('#btn-resume');
  await page.waitForFunction(() => window.__apex.race.state === 'racing' || window.__apex.race.state === 'countdown', null, { timeout: 4000 });

  results.push({ view: 'desktop', errs, menuOverflow, drawn, resultsFit, pauseFit });
  await ctx.close();
}

async function runMobile(browser) {
  const ctx = await browser.newContext({
    viewport: { width: 390, height: 844 }, screen: { width: 390, height: 844 },
    deviceScaleFactor: 1, isMobile: true, hasTouch: true
  });
  const page = await ctx.newPage();
  const errs = [];
  page.on('pageerror', (e) => errs.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errs.push('console: ' + m.text()); });
  await page.goto(URL, { waitUntil: 'domcontentloaded' });
  await waitReady(page);
  await shot(page, 'v-menu-mobile');

  const menuInfo = await page.evaluate(() => {
    const m = document.querySelector('#screen-menu');
    const r = document.querySelector('#btn-start').getBoundingClientRect();
    return {
      scrollH: m.scrollHeight, clientH: m.clientHeight,
      startTop: Math.round(r.top), startBottom: Math.round(r.bottom),
      startVisible: r.top >= 0 && r.bottom <= innerHeight,
      garageVisible: (() => { const g = document.querySelector('#btn-garage').getBoundingClientRect(); return g.bottom <= innerHeight; })()
    };
  });

  await startRaceViaUI(page, 1, 2);
  await page.waitForFunction(() => window.__apex.race.state === 'racing', null, { timeout: 10000 });
  await page.waitForTimeout(900);
  const touch = await page.evaluate(() => {
    const el = document.querySelector('#touch-controls');
    const cs = getComputedStyle(el);
    const buttons = [...el.querySelectorAll('button')].map((b) => {
      const r = b.getBoundingClientRect();
      return { label: b.textContent.trim() || b.getAttribute('aria-label'), top: Math.round(r.top), bottom: Math.round(r.bottom), left: Math.round(r.left), right: Math.round(r.right), visible: r.width > 0 && r.height > 0 };
    });
    return { display: cs.display, buttons, vh: innerHeight, vw: innerWidth };
  });
  await shot(page, 'v-race-mobile');

  // Touch input smoke test: hold gas then steer, checking input state.
  const gasBox = await page.locator('[data-touch="gas"]').boundingBox();
  await page.touchscreen.tap(gasBox.x + gasBox.width / 2, gasBox.y + gasBox.height / 2);
  await page.waitForTimeout(150);
  const steerBox = await page.locator('[data-touch="right"]').boundingBox();
  await page.touchscreen.tap(steerBox.x + steerBox.width / 2, steerBox.y + steerBox.height / 2);

  const drawn = await autopilot(page, { ticks: 20000 });
  log('mobile race result', drawn);
  await page.waitForSelector('#screen-results.is-active', { timeout: 8000 });
  await page.waitForTimeout(350);
  await shot(page, 'v-results-mobile');
  const resultsFit = await modalFits(page, '.results-modal');

  await page.locator('#btn-results-new').click();
  await page.waitForSelector('#screen-draw.is-active', { timeout: 5000 });
  await shot(page, 'v-draw-mobile-back');

  results.push({ view: 'mobile', errs, menuInfo, touch, drawn, resultsFit });
  await ctx.close();
}

async function runLandscape(browser) {
  const ctx = await browser.newContext({
    viewport: { width: 844, height: 390 }, screen: { width: 844, height: 390 },
    deviceScaleFactor: 1, isMobile: true, hasTouch: true
  });
  const page = await ctx.newPage();
  const errs = [];
  page.on('pageerror', (e) => errs.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errs.push('console: ' + m.text()); });
  await page.goto(URL, { waitUntil: 'domcontentloaded' });
  await waitReady(page);
  await shot(page, 'v-menu-land');

  const menuInfo = await page.evaluate(() => {
    const r = document.querySelector('#btn-start').getBoundingClientRect();
    const g = document.querySelector('#btn-garage').getBoundingClientRect();
    return { startVisible: r.top >= 0 && r.bottom <= innerHeight, garageVisible: g.top >= 0 && g.bottom <= innerHeight, scrollH: document.querySelector('#screen-menu').scrollHeight, clientH: document.querySelector('#screen-menu').clientHeight };
  });

  await page.goto(URL + '?demo=race&go=1&track=0', { waitUntil: 'domcontentloaded' });
  await page.waitForFunction(() => window.__apex?.race?.state === 'racing', null, { timeout: 15000 });
  await page.waitForTimeout(900);
  const touch = await page.evaluate(() => {
    const el = document.querySelector('#touch-controls');
    const minimap = document.querySelector('.minimap-panel');
    return {
      controlsDisplay: getComputedStyle(el).display,
      minimapDisplay: getComputedStyle(minimap).display,
      buttonsInView: [...el.querySelectorAll('button')].every((b) => { const r = b.getBoundingClientRect(); return r.top >= 0 && r.bottom <= innerHeight && r.left >= 0 && r.right <= innerWidth; })
    };
  });
  await shot(page, 'v-race-land');

  await page.click('#btn-pause');
  await page.waitForSelector('#screen-pause.is-active', { timeout: 4000 });
  await shot(page, 'v-pause-land');
  const pauseFit = await modalFits(page, '.pause-modal');
  const pauseButtons = await page.evaluate(() => [...document.querySelectorAll('.pause-modal .modal-actions .btn')].map((b) => { const r = b.getBoundingClientRect(); return { text: b.textContent.trim(), visible: r.top >= 0 && r.bottom <= innerHeight && r.width > 0 }; }));

  results.push({ view: 'landscape', errs, menuInfo, touch, pauseFit, pauseButtons });
  await ctx.close();
}

const browser = await chromium.launch({
  executablePath: '/opt/google/chrome/chrome',
  headless: false,
  args: ['--enable-gpu', '--ignore-gpu-blocklist', '--use-angle=swiftshader', '--disable-vulkan-surface']
});

try {
  await runDesktop(browser);
  await runMobile(browser);
  await runLandscape(browser);
} finally {
  await browser.close();
}

