import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/opt/google/chrome/chrome', headless: false, args: ['--enable-gpu', '--ignore-gpu-blocklist'] });
const base = 'http://localhost:3002';

async function pageFor(opts) {
  const ctx = await browser.newContext(opts);
  const page = await ctx.newPage();
  const errs = [];
  page.on('pageerror', (e) => errs.push(e.message));
  page.on('console', (m) => { if (m.type() === 'error') errs.push(m.text()); });
  await page.goto(base, { waitUntil: 'domcontentloaded' });
  await page.waitForFunction(() => window.__apex && getComputedStyle(document.querySelector('#loading')).display === 'none', null, { timeout: 30000 });
  return { ctx, page, errs };
}

async function shot(page, name) {
  await page.screenshot({ path: `/tmp/opencode/${name}.jpg`, type: 'jpeg', quality: 62 });
}

for (const [name, opts] of Object.entries({
  desk: { viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 },
  mobile: { viewport: { width: 390, height: 844 }, screen: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true },
  land: { viewport: { width: 844, height: 390 }, screen: { width: 844, height: 390 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true }
})) {
  const { ctx, page, errs } = await pageFor(opts);

  await page.click('#btn-garage');
  await page.waitForSelector('#screen-garage.is-active', { timeout: 5000 });
  await page.waitForTimeout(900);
  await shot(page, `v-garage-${name}`);
  const garageInfo = await page.evaluate(() => {
    const dock = document.querySelector('.garage-dock');
    const r = dock.getBoundingClientRect();
    return {
      dockFits: r.top >= 0 && r.bottom <= innerHeight + 1,
