import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/opt/google/chrome/chrome', headless: false, args: ['--enable-gpu', '--ignore-gpu-blocklist'] });
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, screen: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
const page = await ctx.newPage();
const errs = [];
page.on('pageerror', (e) => errs.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errs.push(m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => window.__apex && getComputedStyle(document.querySelector('#loading')).display === 'none', null, { timeout: 30000 });
await page.click('#btn-garage');
await page.waitForTimeout(3000);
await page.screenshot({ path: '/tmp/opencode/v-garage-mobile-3s.jpg', type: 'jpeg', quality: 62 });

const swatch = page.locator('#garage-swatches button').nth(4);
console.log('swatch count', await page.locator('#garage-swatches button').count());
await swatch.click();
await page.waitForTimeout(300);
console.log('after swatch', await page.evaluate(() => ({
  hex: document.querySelector('#garage-live-hex').textContent,
  name: document.querySelector('#garage-live-name').textContent,
  body: window.__apex.showroom ? document.querySelector('#garage-hex').value : null
})));

await page.fill('#garage-hex', '22cc88');
await page.press('#garage-hex', 'Enter');
await page.waitForTimeout(300);
console.log('after hex', await page.evaluate(() => document.querySelector('#garage-live-hex').textContent));

await page.locator('[data-sticker]').first().click().catch(async () => {
  await page.locator('#garage-stickers button').first().click();
});
await page.waitForTimeout(300);
console.log('sticker clear disabled', await page.locator('#garage-sticker-clear').isDisabled());
await page.screenshot({ path: '/tmp/opencode/v-garage-mobile-sticker.jpg', type: 'jpeg', quality: 62 });

const dock = page.locator('.garage-dock');
await dock.evaluate((el) => { el.scrollTop = el.scrollHeight; });
await page.waitForTimeout(250);
await page.screenshot({ path: '/tmp/opencode/v-garage-mobile-scrolled.jpg', type: 'jpeg', quality: 62 });
console.log('dock scroll', await dock.evaluate((el) => ({ top: el.scrollTop, max: el.scrollHeight - el.clientHeight })));
console.log('errs', errs);
await browser.close();

