import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/opt/google/chrome/chrome', headless: false, args: ['--enable-gpu', '--ignore-gpu-blocklist'] });

async function open(opts) {
  const ctx = await browser.newContext(opts);
  const page = await ctx.newPage();
  const errs = [];
  page.on('pageerror', (e) => errs.push(e.message));
  page.on('console', (m) => { if (m.type() === 'error') errs.push(m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
  await page.waitForFunction(() => window.__apex && getComputedStyle(document.querySelector('#loading')).display === 'none', null, { timeout: 30000 });
  return { ctx, page, errs };
}

// 1. Bright portrait showroom
{
  const { ctx, page, errs } = await open({ viewport: { width: 390, height: 844 }, screen: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
  await page.click('#btn-garage');
  await page.waitForTimeout(1800);
  await page.screenshot({ path: '/tmp/opencode/v-fix-garage-mobile.jpg', type: 'jpeg', quality: 62 });
  console.log('garage errs', errs);
  await ctx.close();
}

// 2. Landscape race HUD/touch separation
{
  const { ctx, page, errs } = await open({ viewport: { width: 844, height: 390 }, screen: { width: 844, height: 390 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
  await page.goto('http://localhost:3002?demo=race&go=1&track=0', { waitUntil: 'domcontentloaded' });
  await page.waitForFunction(() => window.__apex?.race?.state === 'racing', null, { timeout: 20000 });
  await page.waitForTimeout(700);
  await page.evaluate(() => { const r = window.__apex.race; r.time = 2000; });
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/opencode/v-fix-race-land.jpg', type: 'jpeg', quality: 62 });
  const boxes = await page.evaluate(() => {
    const box = (s) => { const r = document.querySelector(s)?.getBoundingClientRect(); return r && { left: Math.round(r.left), right: Math.round(r.right), top: Math.round(r.top), bottom: Math.round(r.bottom) }; };
    return { speedo: box('.speedo'), steer: box('.touch-steer'), pedals: box('.touch-pedals'), hudBottom: box('.hud-bottom') };
  });
  console.log('land boxes', JSON.stringify(boxes), 'errs', errs);
  await ctx.close();
}

// 3. Small landscape
{
  const { ctx, page, errs } = await open({ viewport: { width: 640, height: 360 }, screen: { width: 640, height: 360 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
  await page.goto('http://localhost:3002?demo=race&go=1&track=1', { waitUntil: 'domcontentloaded' });
  await page.waitForFunction(() => window.__apex?.race?.state === 'racing', null, { timeout: 20000 });
  await page.waitForTimeout(600);
  await page.screenshot({ path: '/tmp/opencode/v-fix-race-land-small.jpg', type: 'jpeg', quality: 62 });
  const overlap = await page.evaluate(() => {
    const box = (s) => { const r = document.querySelector(s)?.getBoundingClientRect(); return r && { left: r.left, right: r.right, top: r.top, bottom: r.bottom }; };
    const s = box('.speedo'), st = box('.touch-steer'), p = box('.touch-pedals');
    const hit = (a, b) => a && b && a.left < b.right && a.right > b.left && a.top < b.bottom && a.bottom > b.top;
    return { s, st, p, speedoSteer: hit(s, st), speedoPedals: hit(s, p), inView: st.right <= innerWidth && p.right <= innerWidth && s.bottom <= innerHeight };
  });
  console.log('small land', JSON.stringify(overlap), 'errs', errs);
  await ctx.close();
}

// 4. No stale toast at countdown
{
  const { ctx, page, errs } = await open({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
  await page.click('#btn-start');
  await page.waitForSelector('#screen-draw.is-active');
  await page.waitForTimeout(700);
  await page.click('#btn-example');
  await page.waitForFunction(() => !document.querySelector('#btn-build').disabled, null, { timeout: 20000 });
  const toastBefore = await page.evaluate(() => document.querySelector('#toast').className);
  await page.click('#btn-build');
  await page.waitForFunction(() => window.__apex.race && window.__apex.race.state === 'countdown', null, { timeout: 15000 });
  await page.waitForTimeout(300);
  const toastAtCountdown = await page.evaluate(() => ({ cls: document.querySelector('#toast').className, text: document.querySelector('#toast').textContent }));
  await page.screenshot({ path: '/tmp/opencode/v-fix-countdown-desk.jpg', type: 'jpeg', quality: 62 });
  console.log('toast', { toastBefore, toastAtCountdown }, 'errs', errs);
  await ctx.close();
}

await browser.close();

