import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/opt/google/chrome/chrome', headless: false, args: ['--enable-gpu', '--ignore-gpu-blocklist'] });
const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
const page = await ctx.newPage();
const errs = [];
page.on('pageerror', (e) => errs.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errs.push(m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => window.__apex && getComputedStyle(document.querySelector('#loading')).display === 'none', null, { timeout: 30000 });
await page.click('#btn-start');
await page.waitForSelector('#screen-draw.is-active');
await page.waitForTimeout(700);
await page.evaluate(() => window.__apex.drawScreen.loadExample(1));
await page.waitForFunction(() => !document.querySelector('#btn-build').disabled, null, { timeout: 20000 });
await page.selectOption('#setup-laps', '3');
await page.selectOption('#setup-ai', '9');
await page.click('#btn-build');
await page.waitForFunction(() => window.__apex.race && ['countdown', 'racing'].includes(window.__apex.race.state), null, { timeout: 20000 });
const setup = await page.evaluate(() => ({ laps: window.__apex.race.totalLaps, ai: window.__apex.race.ai.length, cars: document.querySelector('#hud-position-total').textContent }));
console.log('setup', setup);
await page.evaluate(() => { const r = window.__apex.race; r.countdownT = 3.4; window.__apex.startRaceNow(); });

const out = await page.evaluate(async () => {
  const a = window.__apex;
  const wrap = (v) => Math.atan2(Math.sin(v), Math.cos(v));
  const sleep = () => new Promise((r) => setTimeout(r, 0));
  let ticks = 0;
  let maxSpeed = 0, offroadTicks = 0;
  for (let i = 0; i < 30000; i++) {
    const r = a.race;
    if (!r) break;
    if (r.state === 'finished' && r.resultsShown) break;
    if (r.state === 'racing') {
      const p = r.player;
      const tr = r.track;
      const speed = Math.max(14, Math.abs(p.vLong));
      const ahead = Math.min(120, 22 + speed * 1.2);
      const idx = (Math.floor(p.sNorm * tr.N) + Math.round(ahead / tr.step)) % tr.N;
      const s = tr.samples[idx];
      const err = wrap(Math.atan2(s.x - p.pos.x, s.z - p.pos.z) - p.yaw);
      a.setDemoInput({ left: err > 0.035, right: err < -0.035, gas: false, brake: false });
      maxSpeed = Math.max(maxSpeed, Math.abs(p.vLong) * 3.6);
      if (p.offroad) offroadTicks++;
    }
    a.tick(1 / 60);
    ticks++;
    if (i % 600 === 0) await sleep();
  }
  a.setDemoInput({ left: false, right: false, gas: false, brake: false });
  const r = a.race;
  const p = r.player;
  const finite = ['x', 'z', 'vLong', 'vLat', 'yaw'].every((k) => Number.isFinite(k === 'x' || k === 'z' ? p.pos[k] : p[k]));
  return {
    state: r.state, ticks, maxSpeed, offroadTicks, finite,
    finished: p.finished, laps: p.lapsCompleted, totalLaps: r.totalLaps,
    resultsShown: r.resultsShown,
    position: document.querySelector('#results-position').textContent,
    rows: document.querySelectorAll('#results-rows .results-row').length,
    aiFinished: r.ai.filter((x) => x.finished).length,
    errors: [...document.querySelectorAll('#results-rows .results-row')].length
  };
