import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/opt/google/chrome/chrome', headless: false, args: ['--enable-gpu', '--ignore-gpu-blocklist'] });
const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
const page = await ctx.newPage();
const errs = [];
page.on('pageerror', (e) => errs.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errs.push(m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => window.__apex && getComputedStyle(document.querySelector('#loading')).display === 'none', null, { timeout: 30000 });
await page.click('#btn-start');
await page.waitForSelector('#screen-draw.is-active');
await page.waitForTimeout(700);

const box = await page.locator('#draw-canvas').boundingBox();
async function drawPath(points, close = true) {
  await page.mouse.move(box.x + points[0].x, box.y + points[0].y);
  await page.mouse.down();
  for (let i = 1; i < points.length; i++) {
    await page.mouse.move(box.x + points[i].x, box.y + points[i].y, { steps: 3 });
  }
  if (close) {
    await page.mouse.move(box.x + points[0].x, box.y + points[0].y, { steps: 3 });
  }
  await page.mouse.up();
  await page.waitForTimeout(600);
}

// Smooth loop with a few varied corners.
const w = box.width, h = box.height;
const loop = [
  { x: w * 0.18, y: h * 0.55 }, { x: w * 0.24, y: h * 0.34 }, { x: w * 0.36, y: h * 0.22 },
  { x: w * 0.52, y: h * 0.18 }, { x: w * 0.68, y: h * 0.24 }, { x: w * 0.78, y: h * 0.38 },
  { x: w * 0.82, y: h * 0.56 }, { x: w * 0.72, y: h * 0.72 }, { x: w * 0.56, y: h * 0.8 },
  { x: w * 0.4, y: h * 0.78 }, { x: w * 0.26, y: h * 0.7 }, { x: w * 0.2, y: h * 0.62 }
];
await drawPath(loop);
const valid = await page.evaluate(() => ({
  disabled: document.querySelector('#btn-build').disabled,
  status: document.querySelector('#draw-status').textContent,
  validation: document.querySelector('#validation-title').textContent,
  length: document.querySelector('#stat-length').textContent,
  turns: document.querySelector('#stat-turns').textContent,
  straight: document.querySelector('#stat-straight').textContent,
  points: window.__apex.drawScreen.points.length,
  analyzed: window.__apex.drawScreen.analyzed && { valid: window.__apex.drawScreen.analyzed.valid, turns: window.__apex.drawScreen.analyzed.turns, minRadius: window.__apex.drawScreen.analyzed.minRadius }
}));
console.log('drawn loop', valid);
await page.screenshot({ path: '/tmp/opencode/v-freehand-valid.jpg', type: 'jpeg', quality: 62 });

// Clear and draw a figure-eight (self-intersection should be rejected).
await page.click('#btn-clear');
await page.waitForTimeout(400);
await drawPath([
  { x: w * 0.3, y: h * 0.25 }, { x: w * 0.7, y: h * 0.75 }, { x: w * 0.7, y: h * 0.25 },
  { x: w * 0.3, y: h * 0.75 }, { x: w * 0.3, y: h * 0.25 }
]);
const invalid = await page.evaluate(() => ({
  disabled: document.querySelector('#btn-build').disabled,
  status: document.querySelector('#draw-status').textContent,
  validation: document.querySelector('#validation-title').textContent,
  body: document.querySelector('#validation-body').textContent,
  selfIntersects: window.__apex.drawScreen.analyzed?.selfIntersects,
  points: window.__apex.drawScreen.points.length
}));
console.log('figure-eight', invalid);
await page.screenshot({ path: '/tmp/opencode/v-freehand-invalid.jpg', type: 'jpeg', quality: 62 });
console.log('errs', errs);
await browser.close();

