import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/opt/google/chrome/chrome', headless: false, args: ['--enable-gpu', '--ignore-gpu-blocklist'] });
const ctx = await browser.newContext({ viewport: { width: 640, height: 360 }, screen: { width: 640, height: 360 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
const page = await ctx.newPage();
const errs = [];
page.on('pageerror', (e) => errs.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errs.push(m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => window.__apex && getComputedStyle(document.querySelector('#loading')).display === 'none', null, { timeout: 30000 });
await page.click('#btn-start');
await page.waitForSelector('#screen-draw.is-active');
await page.waitForTimeout(700);
await page.evaluate(() => window.__apex.drawScreen.loadExample(0));
await page.waitForFunction(() => !document.querySelector('#btn-build').disabled, null, { timeout: 20000 });
await page.selectOption('#setup-laps', '1');
await page.selectOption('#setup-ai', '3');
await page.click('#btn-build');
await page.waitForFunction(() => window.__apex.race && ['countdown', 'racing'].includes(window.__apex.race.state), null, { timeout: 20000 });
await page.evaluate(() => { window.__apex.race.countdownT = 3.4; window.__apex.startRaceNow(); });
await page.evaluate(async () => {
  const a = window.__apex;
  const wrap = (v) => Math.atan2(Math.sin(v), Math.cos(v));
  const sleep = () => new Promise((r) => setTimeout(r, 0));
  for (let i = 0; i < 20000; i++) {
    const r = a.race;
    if (!r || (r.state === 'finished' && r.resultsShown)) break;
    if (r.state === 'racing') {
      const p = r.player, tr = r.track;
      const speed = Math.max(14, Math.abs(p.vLong));
      const idx = (Math.floor(p.sNorm * tr.N) + Math.round(Math.min(120, 22 + speed * 1.2) / tr.step)) % tr.N;
      const s = tr.samples[idx];
      const err = wrap(Math.atan2(s.x - p.pos.x, s.z - p.pos.z) - p.yaw);
      a.setDemoInput({ left: err > 0.035, right: err < -0.035, gas: false, brake: false });
    }
    a.tick(1 / 60);
    if (i % 600 === 0) await sleep();
  }
  a.setDemoInput({ left: false, right: false, gas: false, brake: false });
});
await page.waitForSelector('#screen-results.is-active', { timeout: 10000 });
await page.waitForTimeout(300);
const info = await page.evaluate(() => {
  const modal = document.querySelector('.results-modal');
  const action = document.querySelector('.results-actions');
  const r = modal.getBoundingClientRect();
  const a = action.getBoundingClientRect();
  const cs = getComputedStyle(action);
  return {
    modal: { top: Math.round(r.top), bottom: Math.round(r.bottom), scrollH: modal.scrollHeight, clientH: modal.clientHeight, canScroll: modal.scrollHeight > modal.clientHeight },
    actions: { top: Math.round(a.top), bottom: Math.round(a.bottom), inView: a.top >= 0 && a.bottom <= innerHeight, flexDirection: cs.flexDirection },
    rows: document.querySelectorAll('#results-rows .results-row').length
  };
});
console.log(JSON.stringify({ info, errs }, null, 2));
await page.screenshot({ path: '/tmp/opencode/v-results-land-small.jpg', type: 'jpeg', quality: 62 });
await browser.close();

