await page.click('#btn-pause');
await page.waitForSelector('#screen-pause.is-active');
await page.click('#btn-restart-race');
await page.waitForFunction(() => ['countdown', 'racing'].includes(window.__apex.race.state) && !document.querySelector('#screen-pause.is-active'), null, { timeout: 5000 });
const afterRestart = await page.evaluate(() => ({ state: window.__apex.race.state, hudHidden: document.querySelector('#race-hud').classList.contains('is-hidden'), laps: window.__apex.race.totalLaps }));

await page.waitForTimeout(300);
await page.evaluate(() => { if (window.__apex.race.state === 'countdown') window.__apex.startRaceNow(); });
await page.waitForFunction(() => window.__apex.race.state === 'racing', null, { timeout: 5000 });
await page.click('#btn-pause');
