import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/opt/google/chrome/chrome', headless: false, args: ['--enable-gpu', '--ignore-gpu-blocklist'] });
const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
const page = await ctx.newPage();
const errs = [];
page.on('pageerror', (e) => errs.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errs.push(m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => window.__apex && getComputedStyle(document.querySelector('#loading')).display === 'none', null, { timeout: 30000 });
await page.click('#btn-garage');
await page.waitForSelector('#screen-garage.is-active');
await page.waitForTimeout(1800);

const meshInfo = await page.evaluate(() => {
  const root = window.__apex.showroom.car.root;
  let count = 0, frontSide = 0, doubleSide = 0, transparent = 0;
  const names = [];
  root.traverse((o) => {
    if (!o.isMesh) return;
    count++;
    const m = o.material;
    if (m.side === 0) frontSide++;
    if (m.side === 2) doubleSide++;
    if (m.transparent) transparent++;
    names.push({ type: o.geometry.type, side: m.side, transparent: m.transparent, opacity: m.opacity, visible: o.visible });
  });
  return { count, frontSide, doubleSide, transparent, types: [...new Set(names.map((n) => n.type))], names: names.slice(0, 15) };
});
console.log('meshes', JSON.stringify(meshInfo));

const angles = [0, 1.05, 2.1, 3.14, 4.19, 5.24];
for (let i = 0; i < angles.length; i++) {
  if (i > 0) await page.evaluate((d) => window.__apex.showroom.nudgeOrbit(d), angles[i] - angles[i - 1]);
  await page.waitForTimeout(250);
  await page.locator('.garage-stage').screenshot({ path: `/tmp/opencode/garage-angle-${i}.png` });
}
// Look at near side and rear angles
await page.evaluate(() => window.__apex.showroom.resetOrbit());
await page.evaluate(() => window.__apex.showroom.nudgeOrbit(-0.55));
await page.waitForTimeout(300);
await page.locator('.garage-stage').screenshot({ path: '/tmp/opencode/garage-angle-front.png' });
await page.evaluate(() => window.__apex.showroom.nudgeOrbit(2.6));
await page.waitForTimeout(300);
await page.locator('.garage-stage').screenshot({ path: '/tmp/opencode/garage-angle-rear.png' });

// Try double-sided materials for comparison
const changed = await page.evaluate(() => {
  let n = 0;
  window.__apex.showroom.car.root.traverse((o) => {
    if (o.isMesh) { o.material.side = 2; o.material.needsUpdate = true; n++; }
  });
  return n;
});
await page.waitForTimeout(400);
await page.evaluate(() => window.__apex.showroom.resetOrbit());
await page.evaluate(() => window.__apex.showroom.nudgeOrbit(2.6));
await page.waitForTimeout(300);
await page.locator('.garage-stage').screenshot({ path: '/tmp/opencode/garage-double-rear.png' });
console.log('changed', changed, 'errs', errs);
await browser.close();

