import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/opt/google/chrome/chrome', headless: false, args: ['--enable-gpu', '--ignore-gpu-blocklist'] });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
const page = await ctx.newPage();
const errs = [];
page.on('pageerror', (e) => errs.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errs.push(m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => window.__apex && getComputedStyle(document.querySelector('#loading')).display === 'none', null, { timeout: 30000 });
await page.click('#btn-garage');
await page.waitForSelector('#screen-garage.is-active');
await page.waitForTimeout(1500);

// Confirm the tub normals now face outward.
const normals = await page.evaluate(() => {
  const root = window.__apex.showroom.car.root;
  let tub = null;
  root.traverse((o) => { if (!tub && o.isMesh && o.geometry?.type === 'BufferGeometry' && o.geometry.attributes.normal) tub = o; });
  if (!tub) return null;
  const pos = tub.geometry.attributes.position;
  const nor = tub.geometry.attributes.normal;
  let out = 0, inward = 0;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
    const nx = nor.getX(i), ny = nor.getY(i), nz = nor.getZ(i);
    const radial = x * nx + (y - 0.55) * ny;
    if (radial > 0.01) out++; else if (radial < -0.01) inward++;
  }
  return { out, inward, verts: pos.count };
});
console.log('normals', JSON.stringify(normals));

await page.locator('.garage-stage').screenshot({ path: '/tmp/opencode/fix-angle-0.png' });
const startAngle = await page.evaluate(() => window.__apex.showroom.orbitAngle);
const stage = await page.locator('.garage-orbit').boundingBox();
const cx = stage.x + stage.width * 0.5;
const cy = stage.y + stage.height * 0.5;
await page.mouse.move(cx, cy);
await page.mouse.down();
for (let i = 1; i <= 12; i++) {
  await page.mouse.move(cx + i * 20, cy, { steps: 1 });
  await page.waitForTimeout(20);
}
await page.mouse.up();
await page.waitForTimeout(500);
const endAngle = await page.evaluate(() => window.__apex.showroom.orbitAngle);
console.log('drag right angle delta', (endAngle - startAngle).toFixed(3));
await page.locator('.garage-stage').screenshot({ path: '/tmp/opencode/fix-drag-right.png' });

// Flip back and inspect all sides for holes / missing panels.
await page.evaluate(() => window.__apex.showroom.resetOrbit());
await page.waitForTimeout(300);
for (const [i, a] of [1.57, 3.14, 4.71].entries()) {
  await page.evaluate((d) => window.__apex.showroom.nudgeOrbit(d), a);
  await page.waitForTimeout(250);
  await page.locator('.garage-stage').screenshot({ path: `/tmp/opencode/fix-angle-${i + 1}.png` });
}
await page.evaluate(() => window.__apex.showroom.resetOrbit());
await page.waitForTimeout(250);
await page.locator('.garage-stage').screenshot({ path: '/tmp/opencode/fix-angle-front.png' });

// Keyboard: right arrow should turn the same way as dragging right.
const beforeKey = await page.evaluate(() => window.__apex.showroom.orbitAngle);
await page.locator('.garage-orbit').focus();
await page.keyboard.press('ArrowRight');
await page.waitForTimeout(150);
const afterKey = await page.evaluate(() => window.__apex.showroom.orbitAngle);
console.log('arrow right delta', (afterKey - beforeKey).toFixed(3));
console.log('errors', JSON.stringify(errs));
await browser.close();

