import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/opt/google/chrome/chrome', headless: false, args: ['--enable-gpu', '--ignore-gpu-blocklist'] });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
const page = await ctx.newPage();
await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => window.__apex && getComputedStyle(document.querySelector('#loading')).display === 'none', null, { timeout: 30000 });
await page.click('#btn-garage');
await page.waitForSelector('#screen-garage.is-active');
await page.waitForTimeout(1200);
await page.evaluate(() => window.__apex.showroom.resetOrbit());

const noseX = () => page.evaluate(async () => {
  const THREE = await import('/vendor/three.module.js');
  const car = window.__apex.showroom.car;
  const cam = window.__apex.showroom.camera;
  car.root.updateMatrixWorld(true);
  const p = car.root.localToWorld(new THREE.Vector3(0, 0.3, 2.62)).project(cam);
  return p.x;
});

const box = await page.locator('.garage-orbit').boundingBox();
const cx = box.x + box.width / 2;
const cy = box.y + box.height / 2;
const before = await noseX();
await page.mouse.move(cx, cy);
await page.mouse.down();
await page.mouse.move(cx + 60, cy, { steps: 6 });
const afterRight = await noseX();
const angleRight = await page.evaluate(() => window.__apex.showroom.orbitAngle);
await page.mouse.up();
await page.evaluate(() => window.__apex.showroom.resetOrbit());
await page.mouse.move(cx, cy);
await page.mouse.down();
await page.mouse.move(cx - 60, cy, { steps: 6 });
const afterLeft = await noseX();
const angleLeft = await page.evaluate(() => window.__apex.showroom.orbitAngle);
await page.mouse.up();
console.log(JSON.stringify({ before: +before.toFixed(3), afterRight: +afterRight.toFixed(3), angleRight: +angleRight.toFixed(3), afterLeft: +afterLeft.toFixed(3), angleLeft: +angleLeft.toFixed(3) }));
await browser.close();

